catalog_script_client.script:
function onLoad() {
    //Type appropriate comment here, and begin script below
    //decision_rule_v23を取得
    //帳票のIDを取得して、Inputsのパラメータとして
    var catItem = g_form.getUniqueValue();
    var util = new GlideAjax('x_846092_decisio_0.DecisionV2Utils');
    util.addParam('sysparm_name', 'getDecisionv23_Results');
    //DecisionテーブルのInputの変数を設定
    util.addParam('u_id', catItem);
    //util.addParam('u_amount', '');

    util.getXMLAnswer(function(response) {
        var result = JSON.parse(response);
        var u_pattern_1 = result.u_pattern_1;
        var u_step2_1 = result.u_step2_1;
        var u_step2_2 = result.u_step2_2;

        g_form.setValue('u_pattern_1', u_pattern_1);
        g_form.setValue('step2_1', u_step2_1);
        g_form.setValue('step2_2', u_step2_2);


    });
}
